import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.Arrays;

public class VulnerabilityDemoFixed {

    /**
     * Demonstra o uso seguro da API Runtime.exec() passando argumentos como um array.
     * @param command O comando base (ex: "ls").
     * @param arguments Os argumentos do comando (ex: "-l").
     */
    public static void executeCommandSecure(String command, String... arguments) {
        try {
            // Ao passar o comando e seus argumentos como um array de Strings,
            // o Java trata cada elemento como um argumento separado, prevenindo
            // que o input do usuário seja interpretado como um comando adicional.
            ProcessBuilder pb = new ProcessBuilder(command);
            pb.command().addAll(Arrays.asList(arguments));

            Process process = pb.start();

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            System.out.println("--- Saída do Comando Seguro ---");
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            process.waitFor();
        } catch (IOException | InterruptedException e) {
            System.err.println("Erro ao executar o comando: " + e.getMessage());
        }
    }
}
